"""Pure-Python proof of the editable Section input contract; no Blender API."""

from dataclasses import dataclass
from math import dist, isfinite
from numbers import Real


class ContractError(ValueError):
    """The input is ambiguous or inconsistent; explicit editing repair is required."""


